import {
  Box,
  Grid,
  IconButton,
  Paper,
  Skeleton,
  Stack,
  styled,
  Typography,
} from '@mui/material';
import React, { useEffect, useMemo, useState } from 'react';
import { appColors } from '../../../../theme/appColors';
import {
  useGetAllPendingSalesQuery,
  useGetSalesDetailsByOrderIdQuery,
  useSaveRichSalesMutation,
} from '../../../posApi';
import { useAppDispatch, useAppSelector } from '../../../../store/hooks';
import {
  addCustomerDetailes,
  addDiscount,
  addItem,
  BasketItem,
  clearCustomer,
  removeBasket,
  setSaleDetail,
} from '../../store/SalesRichBasketSlice';
import {
  IPendingSalesItem,
  ISaleRichBill,
} from '../../../../core/Interface/saleRich.interface';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import ConfirmationModel from '../../../../components/ModelPopup/ConfirmationModel';
import { useTranslation } from 'react-i18next';
import useSalesRich from '../../useSalesRich';
import { useNotifier } from '../../../../core/Notifier';
import BackdropLoading from '../../../../components/BackdropLoading';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
}));

const MAX_ROW_COUNT = 8;

const PendingSales = () => {
  const { t } = useTranslation(['salesRich']);
  const dispatch = useAppDispatch();
  const { showErrorMessage, showMessage } = useNotifier();
  const { salesDetails } = useSalesRich();

  const [pendingPage, setPendingPage] = useState(0);
  const [openPendingConfirmation, setOpenPendingConfirmation] = useState(false);
  // eslint-disable-next-line max-len
  const [pendingSaleToLoad, setPendingSaleToLoad] = useState<string | null>(null);
  const [originalBasket, setOriginalBasket] = useState<BasketItem[]>([]);
  // eslint-disable-next-line max-len
  const [originalCustomer, setOriginalCustomer] = useState<{ mobile: string; name: string }>({ mobile: '', name: '' });
  // eslint-disable-next-line max-len
  const [originalDiscount, setOriginalDiscount] = useState<{ value: number; isPercentage: boolean }>({ value: 0, isPercentage: false });
  const [isProcessing, setIsProcessing] = useState(false);

  const basketItems = useAppSelector((state) => state.salesRichBasket.items);
  // eslint-disable-next-line max-len
  const pendingSalesId = useAppSelector((state) => state.salesRichBasket.saleId);
  const { data, isLoading } = useGetAllPendingSalesQuery();
  const [saveSales] = useSaveRichSalesMutation();

  // eslint-disable-next-line max-len
  const pendingSalesList = useMemo(() => (data?.data as ISaleRichBill[]) || [], [data?.data]);
  const totalSalesCount = pendingSalesList.length;
  const maxPage = Math.ceil(totalSalesCount / (MAX_ROW_COUNT - 1)) - 1;

  const paginatedSales = useMemo(() => {
    const start = pendingPage * (MAX_ROW_COUNT - 1);
    return pendingSalesList.slice(start, start + (MAX_ROW_COUNT - 1));
  }, [pendingSalesList, pendingPage]);

  const {
    data: psDataById,
    isLoading: loadingPsDataById,
    isFetching,
  // eslint-disable-next-line max-len
  } = useGetSalesDetailsByOrderIdQuery(pendingSalesId, { skip: pendingSalesId === null });

  const normalize = (v?: string | null) => (v ?? '').trim();

  const isSaleModified = () => {
    if (basketItems.length !== originalBasket.length) return true;
    const mapOriginal = new Map(originalBasket.map((item) => [item.id, item]));
    for (const item of basketItems) {
      const original = mapOriginal.get(item.id);
      if (!original) return true;
      // eslint-disable-next-line max-len
      if (item.count !== original.count || item.discountValue !== original.discountValue) return true;
    }
    const origMobile = normalize(originalCustomer.mobile);
    const currentMobile = normalize(salesDetails.mobile);
    if (origMobile === '' && currentMobile !== '') return true;
    if (origMobile !== '' && origMobile !== currentMobile) return true;
    // eslint-disable-next-line max-len
    if (salesDetails.discount !== originalDiscount.value || salesDetails.isDiscountPercentage !== originalDiscount.isPercentage) return true;
    return false;
  };

  useEffect(() => {
    if (!psDataById) return;
    const ItemList = psDataById.data as IPendingSalesItem;
    dispatch(removeBasket());
    // eslint-disable-next-line max-len
    dispatch(addDiscount({ discount: ItemList.discountValue ?? 0, discountAsPercentage: ItemList.isDiscountPercentage ?? false }));
    if (ItemList.customerMobile) {
      // eslint-disable-next-line max-len
      dispatch(addCustomerDetailes({ mobile: ItemList.customerMobile, customerName: ItemList.customerName ?? '' }));
    } else {
      dispatch(clearCustomer());
    }
    dispatch(setSaleDetail(ItemList.saleId?.trim() ?? null));
    const newBasket: BasketItem[] = ItemList.items.map((e) => ({
      id: e.productId, name: e.productName, count: e.qty,
      // eslint-disable-next-line max-len
      discountValue: e.discountValue ?? 0, isDiscountPercentage: e.isDiscountPercentage ?? false,
      unitPrice: e.unitPrice, sn: 1, code: '', categoryName: '', categoryId: '',
      description: '', modifiedBy: '', modifiedOn: '', imageUrl: '', sellingPrice: 0,
      maxDiscountAmount: 0, stockAlertQty: 0, reOrderQty: 0,
      defaultDiscountAmount: e.discountValue ?? e.discount ?? 0, expiryDate: '',
      isEnabled: true, isKgOrLitre: false, isOnlineOrder: true,
      createdBy: '', updatedBy: '', createdDate: '', updatedDate: '', currentStock: 0,
    }));
    newBasket.forEach((item) => dispatch(addItem(item)));
    setOriginalBasket(newBasket);
    // eslint-disable-next-line max-len
    setOriginalCustomer({ mobile: ItemList.customerMobile ?? '', name: ItemList.customerName ?? '' });
    // eslint-disable-next-line max-len
    setOriginalDiscount({ value: ItemList.discountValue ?? 0, isPercentage: ItemList.isDiscountPercentage ?? false });
  }, [dispatch, psDataById]);

  useEffect(() => {
    if (totalSalesCount === 0) resetPendingState();
    if (pendingPage > maxPage) setPendingPage(0);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [totalSalesCount, maxPage, pendingPage]);

  const resetPendingState = () => {
    setPendingPage(0);
    dispatch(removeBasket());
    dispatch(clearCustomer());
    dispatch(setSaleDetail(null));
    dispatch(addDiscount({ discount: 0, discountAsPercentage: false }));
    setOriginalBasket([]);
    setOriginalCustomer({ mobile: '', name: '' });
    setOriginalDiscount({ value: 0, isPercentage: false });
  };

  const handlePendingSale = (id: string) => {
    setOriginalBasket([]);
    setOriginalCustomer({ mobile: '', name: '' });
    setOriginalDiscount({ value: 0, isPercentage: false });
    dispatch(setSaleDetail(null));
    setTimeout(() => dispatch(setSaleDetail(id)), 0);
  };

  const saveCurrentSale = async (): Promise<boolean> => {
    if (!isSaleModified()) return true;
    try {
      const res = await saveSales({ ...salesDetails, paymentMethod: '', isPaid: false }).unwrap();
      if (!res.status) { showErrorMessage(res.message); return false; }
      showMessage(res.message);
      dispatch(removeBasket());
      return true;
    } catch (e) { showErrorMessage((e as Error).message); return false; }
  };

  const handlePendingClick = (id: string) => {
    if (isFetching || loadingPsDataById) return;
    if (pendingSalesId === id) return;
    if (basketItems.length === 0) { handlePendingSale(id); return; }
    // eslint-disable-next-line max-len
    if (isSaleModified()) { setPendingSaleToLoad(id); setOpenPendingConfirmation(true); }
    else loadPendingSale(id);
  };

  const loadPendingSale = (id: string) => {
    if (!id) return;
    dispatch(removeBasket());
    dispatch(clearCustomer());
    dispatch(setSaleDetail(null));
    setTimeout(() => dispatch(setSaleDetail(id)), 0);
  };

  const confirmPendingSale = async () => {
    if (!pendingSaleToLoad || isProcessing) return;
    setIsProcessing(true);
    try {
      const saved = await saveCurrentSale();
      if (saved) handlePendingSale(pendingSaleToLoad);
    } finally {
      setPendingSaleToLoad(null);
      setOpenPendingConfirmation(false);
      setIsProcessing(false);
    }
  };

  const cancelPendingSale = () => {
    if (pendingSaleToLoad) handlePendingSale(pendingSaleToLoad);
    setPendingSaleToLoad(null);
    setOpenPendingConfirmation(false);
  };

  return (
    <Box>
      {!isLoading && (
        <Grid
          container
          spacing={1}
        >
          {paginatedSales.map((item) => (
            <Grid
              item
              key={item.id}
              md={1.5}
              sm={1.5}
              xs={4}
            >
              <Item
                onClick={() => handlePendingClick(item.id)}
                sx={{
                  background: 'linear-gradient(135deg, #f1f5f9 0%, #e2e8f0 100%)',
                  border: '2px solid transparent',
                  borderBottom: pendingSalesId === item.id
                    ? '4px solid #2563EB'
                    : '2px solid transparent',
                  boxShadow: 'none',
                  cursor: 'pointer',
                  transition: 'all 0.15s',
                }}
              >
                <Stack
                  alignItems="center"
                  direction="column"
                >
                  <Typography
                    sx={{
                      color: '#0F1D4D',
                      fontSize: 12,
                      fontWeight: 800,
                      letterSpacing: '0.3px',
                      textAlign: 'center',
                    }}
                  >
                    {item.invoiceId}
                  </Typography>
                </Stack>
              </Item>
            </Grid>
          ))}

          {/* Empty filler */}
          {/* eslint-disable-next-line max-len */}
          {Array.from(Array(MAX_ROW_COUNT - 1 - paginatedSales.length).keys()).map((k) => (
            <Grid
              item
              key={'empty' + k}
              md={1.5}
              sm={1.5}
              xs={4}
            >
              <Item
                sx={{
                  background: 'rgba(148,163,184,0.15)',
                  cursor: 'default',
                }}
              />
            </Grid>
          ))}

          {/* Pagination */}
          <Grid
            item
            md={1.5}
            sm={1.5}
            xs={4}
          >
            <Item
              sx={{
                background: '#0F1D4D',
                cursor: 'default',
              }}
            >
              <Grid container>
                <Grid
                  item
                  sm={6}
                >
                  <IconButton
                    disabled={pendingPage <= 0}
                    onClick={() => setPendingPage((p) => p - 1)}
                    size="small"
                    sx={{ color: appColors.white, '&:disabled': { color: 'rgba(255,255,255,0.3)' } }}
                  >
                    <ArrowBackIosNewIcon sx={{ fontSize: 22 }} />
                  </IconButton>
                </Grid>
                <Grid
                  item
                  sm={6}
                >
                  <IconButton
                    disabled={pendingPage >= maxPage}
                    onClick={() => setPendingPage((p) => p + 1)}
                    size="small"
                    sx={{ color: appColors.white, '&:disabled': { color: 'rgba(255,255,255,0.3)' } }}
                  >
                    <ArrowForwardIosIcon sx={{ fontSize: 22 }} />
                  </IconButton>
                </Grid>
              </Grid>
            </Item>
          </Grid>
        </Grid>
      )}

      {isLoading && (
        <Grid
          container
          spacing={1}
        >
          {[...Array(MAX_ROW_COUNT)].map((_, idx) => (
            <Grid
              item
              key={idx}
              md={1.5}
              sm={1.5}
              xs={4}
            >
              <Skeleton
                height={'var(--tile-h)'}
                sx={{ borderRadius: '10px' }}
                variant="rectangular"
              />
            </Grid>
          ))}
        </Grid>
      )}

      {openPendingConfirmation && (
        <ConfirmationModel
          content={t('salesRich:confirmPendingClickMessage')}
          handleClose={cancelPendingSale}
          isProcessing={isProcessing}
          onConfirm={confirmPendingSale}
          open={openPendingConfirmation}
          title={t('salesRich:confirmPendingSaleTitle')}
        />
      )}
      <BackdropLoading isLoading={isFetching || loadingPsDataById} />
    </Box>
  );
};

export default React.memo(PendingSales);
