import React, { useEffect, useMemo } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import SearchOutlinedIcon from '@mui/icons-material/SearchOutlined';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useSearchOrderByIdQuery } from '../../posApi';
import { IPreOrderJewellery } from '../../../core/Interface/preOrderJewellery.interface';
import { useAppDispatch } from '../../../store/hooks';
import {
  addCustomerDetailes,
  addDiscount,
  addItem,
  addPaymentMethod,
  addReceivedMoney,
  removeBasket,
  setIsGetOrderIdValues,
  setReferenceId,
} from '../store/BasketSlice';
import { useNotifier } from '../../../core/Notifier';
import { IProductData } from '../../../core/Interface/product.interface';

interface IFindOrder {
  open: boolean;
  handleClose: (close: boolean) => void;
  products: IProductData[];
}

const FindOrder: React.FC<IFindOrder> = ({ open, handleClose, products }) => {
  const [searchQuery, setSearchQuery] = React.useState('');
  const dispatch = useAppDispatch();
  const [orderId, setOrderId] = React.useState('');
  const [, setShowOrderIdAlert] = React.useState(false);
  const { data, error, isFetching } = useSearchOrderByIdQuery(
    orderId.split('_')[0],
    { skip: !orderId }
  );

  const handleSearch = () => {
    if (!searchQuery) return;
    dispatch(removeBasket());
    setOrderId(searchQuery);
  };

  const productMap = useMemo(() => {
    const map = new Map<string, string>();
    products.forEach((item: IProductData) => {
      map.set(item.id, item.name ?? '');
    });
    return map;
  }, [products]);

  const { showErrorMessage, showMessage } = useNotifier();

  useEffect(() => {
    if (error) {
      const err = error as {
        status: number;
        data?: {
          code?: number;
          status?: boolean;
          message?: string;
          data?: string;
        };
      };

      const msg =
        err.data?.data || err.data?.message || 'Unknown error occurred!';

      showErrorMessage(msg);

      return;
    }
    if (data) {
      if (data.status === false || !data.data) {
        const msg =
          (typeof data.data === 'string' ? data.data : data.message) ||
          'Order not found';
        showErrorMessage(msg);
        return;
      }
      const order = data.data;

      if (typeof data.data !== 'object') {
        showErrorMessage('Order not found');
        return;
      }
      const orderObj = order as IPreOrderJewellery;

      if (orderObj.status?.toLowerCase() === 'complete') {
        showErrorMessage(data.message || 'Order already completed');
        return;
      }

      if (!orderObj.customerName?.mobile) {
        setShowOrderIdAlert(true);
        return;
      }
      showMessage('Data Successfully Retrived!');

      const dateOnly = orderObj.deliveryDateTime?.split('T')[0] ?? '';

      dispatch(
        addCustomerDetailes({
          mobile: orderObj.customerName.mobile,
          customerName: orderObj.customerName.name,
          deliveryDateTime: dateOnly,
        })
      );

      dispatch(setIsGetOrderIdValues(true));
      dispatch(addPaymentMethod(orderObj.paymentMethod));
      dispatch(addReceivedMoney(orderObj.received ?? 0));
      dispatch(setReferenceId(orderObj.id));

      dispatch(
        addDiscount({
          discount: orderObj.discount,
          discountAsPercentage: orderObj.isDiscountPercentage,
        })
      );

      orderObj.items.forEach((item) => {
        dispatch(
          addItem({
            ...item,
            count: item.qty ?? 1,
            goldPrice8g: item.unitPrice ?? 0,
            goldWasteQty: item.goldWasteQty ?? 0,
            goldCarrot: item.goldCarrot ?? '22K',
            calculatedUnitPrice: item.calculatedUnitPrice ?? 0,
            name:
              (item.productId && productMap.get(item.productId)) ??
              item.name ??
              '',
            id: item.productId ?? '',
            amount: item.amount ?? 0,
          })
        );
      });

      handleClose(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [data, error]);

  return (
    <>
      <Dialog
        fullWidth
        maxWidth="sm"
        open={open}
        PaperProps={{ sx: { borderRadius: '12px', overflow: 'hidden' } }}
      >
        <DialogTitle sx={{ p: 0 }}>
          <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
            <Stack alignItems="center" direction="row" spacing={1.5}>
              <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                <SearchOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
              </Box>
              <Box>
                <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>Search Order by Id</Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Find order by ID or bill number</Typography>
              </Box>
            </Stack>
          </Box>
        </DialogTitle>

        <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
          <Grid
            container
            spacing={2}
            sx={{ pt: 1 }}
          >
            <Grid
              item
              md={9}
              xs={12}
            >
              <TextField
                autoFocus
                fullWidth
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Enter order id or bill id"
                size="small"
                value={searchQuery}
              />
            </Grid>

            <Grid
              item
              md={3}
              xs={12}
            >
              <Button
                disabled={isFetching}
                onClick={handleSearch}
                sx={{ background: HEADER_GRADIENT, color: '#fff', borderRadius: '8px', height: 40, textTransform: 'none' }}
                variant="contained"
              >
                {isFetching ? 'Searching...' : 'Search'}
              </Button>
            </Grid>
          </Grid>
        </DialogContent>

        <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
          <Button
            color="primary"
            onClick={() => handleClose(false)}
            sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
            variant="outlined"
          >
            Close
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default React.memo(FindOrder);