import {
  Autocomplete,
  Box,
  CircularProgress,
  Grid,
  InputAdornment,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import SearchIcon from '@mui/icons-material/Search';
import Person2TwoToneIcon from '@mui/icons-material/Person2TwoTone';
import {
  useLazySearchCustomerByMobileQuery,
  useGetAllForSaleQuery,
} from '../../posApi';
import AddMobile from './AddMobile';
import AlertPopup from './Kgpopup';
import { useAppDispatch } from '../../../store/hooks';
import { useSelector } from 'react-redux';
import { addCustomer } from '../store/BasketSelector';
import { addCustomerDetailes, addItem } from '../store/BasketSlice';
import { ICustomerData } from '../../../core/Interface/customer.interface';
import { IProduct, IProductData } from '../../../core/Interface/product.interface';
import { IJewelleryBasketItem } from '../../../core/Interface/saleJewellery.interface';
import { getPriceFormatWithoutCurrency } from '../../../core/utils';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const ITEM_H = 44;
const MAX_VISIBLE = 8;

// ── Virtualised listbox (same pattern as SalesRich SearchProduct) ─────────────
const VirtualListbox = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLElement>
>(function VirtualListbox({ children, style, ...other }, ref) {
  const items = React.Children.toArray(children);
  const scrollRef = useRef<HTMLDivElement>(null);

  const virtualizer = useVirtualizer({
    count: items.length,
    estimateSize: () => ITEM_H,
    getScrollElement: () => scrollRef.current,
    overscan: 5,
  });

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = 0;
  }, [items.length]);

  const height = Math.min(items.length * ITEM_H, ITEM_H * MAX_VISIBLE);

  return (
    <div ref={ref} style={{ ...style, overflow: 'hidden', padding: '4px 0' }} {...other}>
      <div ref={scrollRef} style={{ height, overflowY: 'auto' }}>
        <div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>
          {virtualizer.getVirtualItems().map((vi) => (
            <div
              key={vi.index}
              style={{
                left: 0,
                position: 'absolute',
                right: 0,
                top: 0,
                transform: `translateY(${vi.start}px)`,
              }}
            >
              {items[vi.index]}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
});

// ─────────────────────────────────────────────────────────────────────────────

const JewelleryCustomer = () => {
  const dispatch = useAppDispatch();
  const basket = useSelector(addCustomer);

  // ── Mobile number search ──────────────────────────────────────────────────
  const [mobileNumber, setMobileNumber] = useState<string>('');
  const [prevMobile, setPrevMobile] = useState<string>('');
  const [hasSearched, setHasSearched] = useState(false);
  const [openAddMobile, setOpenAddMobile] = useState(false);
  const mobileInputRef = useRef<HTMLInputElement>(null);

  const [triggerSearch, { data: customerResult, isLoading: custLoading, isFetching: custFetching }] =
    useLazySearchCustomerByMobileQuery();

  const isSearching = custLoading || custFetching;

  const customerDataMemo = useMemo(
    () => (customerResult?.data as ICustomerData[]) ?? [],
    [customerResult?.data]
  );

  const safeTriggerSearch = (mobile: string, force = false) => {
    if (!mobile) return;
    if (!force && mobile === prevMobile) return;
    setPrevMobile(mobile);
    triggerSearch(mobile);
    setHasSearched(true);
  };

  const handleMobileKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && (mobileNumber.length === 9 || mobileNumber.length === 10)) {
      safeTriggerSearch(mobileNumber, true);
    }
  };

  const handleMobileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val.length <= 10 && /^\d*$/.test(val)) setMobileNumber(val);
  };

  useEffect(() => {
    if (hasSearched && !isSearching && customerDataMemo.length === 0) {
      setOpenAddMobile(true);
    }
  }, [isSearching, customerDataMemo, hasSearched]);

  useEffect(() => {
    if (customerDataMemo.length > 0) {
      const c = customerDataMemo[0];
      dispatch(addCustomerDetailes({ mobile: c.mobile, customerName: c.name }));
    }
  }, [customerDataMemo, dispatch]);

  useEffect(() => {
    if (basket.mobile) {
      setMobileNumber(basket.mobile);
      setPrevMobile(basket.mobile);
      setHasSearched(false);
      setOpenAddMobile(false);
      if (basket.mobile.length === 9 || basket.mobile.length === 10) {
        safeTriggerSearch(basket.mobile);
      }
    } else {
      setMobileNumber('');
      setPrevMobile('');
      setHasSearched(false);
      setOpenAddMobile(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [basket.mobile]);

  // ── Product search ────────────────────────────────────────────────────────
  const { data: productsData } = useGetAllForSaleQuery({ pageIndex: 0, pageSize: 5000, searchText: '' });

  const allProducts = useMemo(
    () => (productsData?.data as IProduct)?.records ?? [],
    [productsData?.data]
  );

  const [productSearchValue, setProductSearchValue] = useState<string>('');
  const [selectedProduct, setSelectedProduct] = useState<IProductData | null>(null);
  const [openKgPopup, setOpenKgPopup] = useState(false);

  // Show all products on empty click; filter when typing — same as SalesRich
  const filteredProductOptions = useMemo(() => {
    const q = productSearchValue.toLowerCase().trim();
    if (!q) return allProducts;
    return allProducts.filter(
      (o) => o.name.toLowerCase().includes(q) || o.code.toLowerCase().includes(q)
    );
  }, [allProducts, productSearchValue]);

  const handleProductChange = (
    _: React.SyntheticEvent,
    newValue: string | IProductData | null,
  ) => {
    if (newValue && typeof newValue === 'object' && 'id' in newValue) {
      setSelectedProduct(newValue as IProductData);
      setOpenKgPopup(true);
      setProductSearchValue('');
    }
  };

  const handleAdd = (
    calculatedValue: number | null,
    inputCount: number,
    goldData?: {
      goldWeightQty: number;
      goldWasteQty: number;
      goldCarrot: string;
      makingCharge: number;
      goldPrice8g: number;
    }
  ) => {
    if (selectedProduct && calculatedValue !== null) {
      const variantId = `${selectedProduct.id}__v${Math.floor(Math.random() * 20) + 10}`;
      const basketItem: IJewelleryBasketItem = {
        ...selectedProduct,
        id: variantId,
        unitPrice: calculatedValue,
        calculatedUnitPrice: calculatedValue,
        count: inputCount || 1,
        goldWeightQty: goldData?.goldWeightQty ?? 0,
        goldWasteQty: goldData?.goldWasteQty ?? 0,
        goldCarrot: goldData?.goldCarrot ?? '22K',
        makingCharge: goldData?.makingCharge ?? 0,
        goldPrice8g: goldData?.goldPrice8g ?? 0,
      };
      dispatch(addItem(basketItem));
      setOpenKgPopup(false);
      setSelectedProduct(null);
    }
  };

  // ── Render ────────────────────────────────────────────────────────────────
  return (
    <Box
      sx={{
        p: '10px 10px 8px 10px',
        backgroundColor: '#fff',
        borderBottom: '1px solid rgba(15,29,77,0.08)',
      }}
    >
      <Grid container spacing={1} sx={{ pb: basket.mobile ? 1.5 : 0 }}>
        {/* Mobile number */}
        <Grid item xs={6}>
          <TextField
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  {isSearching ? (
                    <CircularProgress size={16} sx={{ color: TEAL }} />
                  ) : (
                    <SearchIcon
                      onClick={() => {
                        if (mobileNumber.length === 9 || mobileNumber.length === 10)
                          safeTriggerSearch(mobileNumber, true);
                      }}
                      sx={{
                        color: mobileNumber.length === 9 || mobileNumber.length === 10
                          ? TEAL : alpha(NAVY, 0.3),
                        cursor: mobileNumber.length === 9 || mobileNumber.length === 10
                          ? 'pointer' : 'default',
                        fontSize: 17,
                        transition: 'color 0.15s',
                      }}
                    />
                  )}
                </InputAdornment>
              ),
            }}
            autoComplete="off"
            autoFocus
            disabled={isSearching}
            fullWidth
            inputProps={{ maxLength: 10 }}
            inputRef={mobileInputRef}
            onChange={handleMobileChange}
            onKeyDown={handleMobileKeyDown}
            placeholder="Mobile number…"
            size="small"
            sx={{
              '& .MuiOutlinedInput-input': { fontSize: 13 },
              '& .MuiOutlinedInput-root': {
                backgroundColor: '#fff',
                borderRadius: '10px',
                transition: 'box-shadow 0.2s',
                '& fieldset': {
                  borderColor: isSearching ? TEAL : alpha(NAVY, 0.18),
                  borderWidth: isSearching ? '1.5px' : '1px',
                  transition: 'border-color 0.2s',
                },
                '&.Mui-focused fieldset': { borderColor: TEAL, borderWidth: '1.5px' },
                '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
                '&.Mui-disabled': { backgroundColor: alpha(TEAL, 0.03) },
                '&.Mui-disabled fieldset': { borderColor: alpha(TEAL, 0.35), borderWidth: '1.5px' },
              },
            }}
            value={mobileNumber}
            variant="outlined"
          />
        </Grid>

        {/* Product search — matches SalesRich SearchProduct */}
        <Grid item xs={6}>
          <Autocomplete<IProductData, false, false, true>
            ListboxComponent={VirtualListbox as React.ComponentType<React.HTMLAttributes<HTMLElement>>}
            freeSolo
            getOptionLabel={(opt) => (typeof opt === 'string' ? opt : opt.name ?? '')}
            id="jewellery-product-search"
            inputValue={productSearchValue}
            isOptionEqualToValue={(opt, val) => {
              if (typeof opt === 'string' || typeof val === 'string') return false;
              return opt.id === val.id;
            }}
            onChange={handleProductChange}
            onInputChange={(_, v) => setProductSearchValue(v)}
            options={filteredProductOptions}
            renderInput={(params) => (
              <TextField
                {...params}
                InputProps={{
                  ...params.InputProps,
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: TEAL, fontSize: 17 }} />
                    </InputAdornment>
                  ),
                  type: 'search',
                }}
                autoComplete="off"
                placeholder="Search name or code…"
                size="small"
                sx={{
                  '& .MuiOutlinedInput-input': { fontSize: 13 },
                  '& .MuiOutlinedInput-root': {
                    backgroundColor: '#fff',
                    borderRadius: '10px',
                    '& fieldset': { borderColor: alpha(NAVY, 0.18) },
                    '&.Mui-focused fieldset': { borderColor: TEAL, borderWidth: '1.5px' },
                    '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
                  },
                }}
                variant="outlined"
              />
            )}
            renderOption={(props, option) => {
              if (typeof option === 'string') return <li {...props}>{option}</li>;
              return (
                <li
                  {...props}
                  key={option.id}
                  style={{ borderRadius: '8px', cursor: 'pointer', padding: '6px 10px' }}
                >
                  <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, width: '100%' }}>
                    <Box
                      sx={{
                        background: TEAL,
                        borderRadius: '2px',
                        flexShrink: 0,
                        height: 26,
                        width: 3,
                      }}
                    />
                    <Box sx={{ flex: 1, minWidth: 0 }}>
                      <Typography
                        sx={{
                          color: NAVY,
                          fontSize: 12,
                          fontWeight: 700,
                          lineHeight: 1.3,
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                          whiteSpace: 'nowrap',
                        }}
                      >
                        {option.name}
                      </Typography>
                      {option.code && (
                        <Typography sx={{ color: alpha(NAVY, 0.42), fontSize: 10, lineHeight: 1.2 }}>
                          {option.code}
                        </Typography>
                      )}
                    </Box>
                    {option.unitPrice !== undefined && (
                      <Typography
                        sx={{
                          color: TEAL,
                          flexShrink: 0,
                          fontSize: 11,
                          fontVariantNumeric: 'tabular-nums',
                          fontWeight: 800,
                        }}
                      >
                        {getPriceFormatWithoutCurrency(option.unitPrice)}
                      </Typography>
                    )}
                  </Box>
                </li>
              );
            }}
            slotProps={{
              paper: {
                sx: {
                  border: `1px solid ${alpha(TEAL, 0.15)}`,
                  borderRadius: '12px',
                  boxShadow: `0 8px 32px ${alpha(NAVY, 0.16)}`,
                  mt: 0.5,
                  '& .MuiAutocomplete-option': {
                    '&:hover, &.Mui-focused': { background: alpha(TEAL, 0.08) },
                    '&[aria-selected="true"]': { background: alpha(TEAL, 0.12) },
                  },
                },
              },
            }}
            sx={{ width: '100%' }}
            value={null}
          />
        </Grid>
      </Grid>

      {/* Compact customer profile */}
      {basket.mobile && (
        <Stack direction="row" alignItems="center" gap={1} sx={{ mt: 0.5 }}>
          <Box
            sx={{
              alignItems: 'center',
              background: alpha(TEAL, 0.1),
              borderRadius: '8px',
              color: TEAL,
              display: 'flex',
              flexShrink: 0,
              height: 30,
              justifyContent: 'center',
              width: 30,
            }}
          >
            <Person2TwoToneIcon sx={{ fontSize: 18 }} />
          </Box>
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography
              sx={{
                color: NAVY,
                fontSize: 13,
                fontWeight: 800,
                lineHeight: 1.2,
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}
            >
              {basket.customerName || customerDataMemo[0]?.name || ''}
            </Typography>
            <Typography sx={{ color: '#94A3B8', fontSize: 10, fontWeight: 500 }}>
              {basket.mobile}
            </Typography>
          </Box>
        </Stack>
      )}

      {/* Dialogs */}
      {openAddMobile && (
        <AddMobile
          customers=""
          handleCloseDialog={() => {
            setOpenAddMobile(false);
            setHasSearched(false);
          }}
          openModel={openAddMobile}
          title="Add Customer"
        />
      )}

      {selectedProduct && openKgPopup && (
        <AlertPopup
          handleAdd={handleAdd}
          handleCloseAlert={() => {
            setOpenKgPopup(false);
            setSelectedProduct(null);
          }}
          open={openKgPopup}
          product={selectedProduct}
        />
      )}
    </Box>
  );
};

export default React.memo(JewelleryCustomer);
