import { Autocomplete, Box, InputAdornment, TextField, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import SearchIcon from '@mui/icons-material/Search';
import useScanDetection from 'use-scan-detection-react18';
import useSalesRich from '../../useSalesRich';
import { useAppDispatch } from '../../../../store/hooks';
import { addItem, BasketItem } from '../../store/SalesRichBasketSlice';
import { IProductData } from '../../../../core/Interface/product.interface';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import KgPopup from '../SalesRight/components/KgPopup';

const TEAL  = '#0F8B8D';
const NAVY  = '#0F1D4D';
const ITEM_H     = 44;
const MAX_VISIBLE = 8;

const normalizeLookupValue = (value: string) =>
  value.replace(/Shift/g, '').trim().toLowerCase();

// ── Virtualized listbox ───────────────────────────────────────────────────────
// eslint-disable-next-line react/no-multi-comp
const VirtualListbox = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLElement>
>(function VirtualListbox({ children, style, ...other }, ref) {
  const items  = React.Children.toArray(children);
  const scrollRef = useRef<HTMLDivElement | null>(null);

  // MUI's listbox element is itself the scroll container.
  // Must be a stable callback: a new ref fn each render makes MUI re-register
  // the listbox, which resets the highlight and jumps scrollTop back to 0.
  const setRefs = useCallback(
    (node: HTMLDivElement | null) => {
      scrollRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  const virtualizer = useVirtualizer({
    count: items.length,
    estimateSize: () => ITEM_H,
    getScrollElement: () => scrollRef.current,
    overscan: 5,
  });

  // scroll to top whenever result set changes
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = 0;
  }, [items.length]);

  return (
    <div
      ref={setRefs}
      {...other}
      style={{
        ...style,
        maxHeight: `min(${ITEM_H * MAX_VISIBLE}px, 50vh)`,
        overflowY: 'auto',
        padding: '4px 0',
      }}
    >
      <div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>
        {virtualizer.getVirtualItems().map((vi) => (
          <div
            data-index={vi.index}
            key={vi.index}
            ref={virtualizer.measureElement}
            style={{
              left: 0,
              position: 'absolute',
              right: 0,
              top: 0,
              transform: `translateY(${vi.start}px)`,
            }}
          >
            {items[vi.index]}
          </div>
        ))}
      </div>
    </div>
  );
});

// ── Main component ────────────────────────────────────────────────────────────
// eslint-disable-next-line react/no-multi-comp
const SearchProduct = () => {
  const dispatch = useAppDispatch();
  const { categoryMemo, currencyCode } = useSalesRich();
  const [searchValue, setSearchValue] = useState<string>('');
  const [openShowPopup, setOpenShowPopup] = useState(false);
  const [selectedProduct, setSelectedProduct] =
    useState<IProductData | null>(null);

  const productMemo = useMemo(
    () =>
      Object.entries(categoryMemo).flatMap(([, arr]) =>
        arr.map((obj) => ({ ...obj })),
      ),
    [categoryMemo],
  );

  const filteredProducts = useMemo(() => {
    if (!searchValue) return productMemo;
    const q = searchValue.toLowerCase().trim();
    return productMemo.filter(
      (p) =>
        p.name?.toLowerCase().includes(q) ||
        p.code?.toLowerCase().includes(q),
    );
  }, [productMemo, searchValue]);

  const findMatchingProduct = (value: string) => {
    const normalized = normalizeLookupValue(value);
    if (!normalized) return null;

    const exactCodeMatch = productMemo.find(
      (product) => product.code?.toLowerCase() === normalized,
    );
    if (exactCodeMatch) return exactCodeMatch;

    const exactNameMatch = productMemo.find(
      (product) => product.name?.toLowerCase() === normalized,
    );
    if (exactNameMatch) return exactNameMatch;

    const partialMatches = productMemo.filter(
      (product) =>
        product.code?.toLowerCase().includes(normalized) ||
        product.name?.toLowerCase().includes(normalized),
    );

    return partialMatches.length === 1 ? partialMatches[0] : null;
  };

  const addProductToBasket = (product: IProductData) => {
    setSearchValue('');
    if (product.isKgOrLitre) {
      setSelectedProduct(product);
      setOpenShowPopup(true);
      return;
    }
    dispatch(addItem({ ...product, count: 1 } as BasketItem));
  };

  const handleAdd = (calculatedValue: number | null, inputCount: number) => {
    if (selectedProduct && calculatedValue !== null) {
      const basketItem: BasketItem = { ...selectedProduct, count: inputCount };
      dispatch(addItem(basketItem));
      setOpenShowPopup(false);
      setSelectedProduct(null);
    }
  };

  const handleClosePopup = () => {
    setOpenShowPopup(false);
    setSelectedProduct(null);
  };

  useScanDetection({
    onComplete: (code) => {
      const matchedProduct = findMatchingProduct(String(code));
      if (matchedProduct) {
        addProductToBasket(matchedProduct);
      }
    },
  });

  const handleChange = (
    _event: React.SyntheticEvent,
    newValue: string | IProductData | null,
  ) => {
    if (newValue && typeof newValue === 'object' && 'id' in newValue) {
      addProductToBasket(newValue as IProductData);
    }
  };

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter' && searchValue.trim()) {
      event.preventDefault();
    }
  };

  return (
    <Box sx={{ width: '100%' }}>
      <Autocomplete
        // eslint-disable-next-line max-len
        ListboxComponent={VirtualListbox as React.ComponentType<React.HTMLAttributes<HTMLElement>>}
        filterOptions={(options) => options}
        freeSolo
        getOptionLabel={(option) =>
          typeof option === 'string' ? option : option.name || ''
        }
        id="salesrich-product-search"
        inputValue={searchValue}
        isOptionEqualToValue={(option, value) => {
          if (typeof option === 'string' || typeof value === 'string') {
            return false;
          }
          return option.id === value.id;
        }}
        onChange={handleChange}
        onInputChange={(_e, v) => setSearchValue(v)}
        options={filteredProducts}
        renderInput={(params) => (
          <TextField
            {...params}
            InputProps={{
              ...params.InputProps,
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon sx={{ color: TEAL, fontSize: 17 }} />
                </InputAdornment>
              ),
              type: 'search',
            }}
            fullWidth
            onKeyDown={handleKeyDown}
            placeholder="Search name or code…"
            size="small"
            sx={{
              '& .MuiOutlinedInput-input': { fontSize: 13 },
              '& .MuiOutlinedInput-root': {
                backgroundColor: '#fff',
                borderRadius: '10px',
                '& fieldset': { borderColor: alpha(NAVY, 0.18) },
                '&.Mui-focused fieldset': {
                  borderColor: TEAL,
                  borderWidth: '1.5px',
                },
                '&:hover fieldset': { borderColor: alpha(TEAL, 0.5) },
              },
            }}
          />
        )}
        renderOption={(props, option) => {
          if (typeof option === 'string') {
            return <li {...props}>{option}</li>;
          }
          return (
            <li
              {...props}
              key={option.id}
              style={{
                borderRadius: '8px',
                cursor: 'pointer',
                padding: '6px 10px',
              }}
            >
              <Box sx={{ alignItems: 'center', display: 'flex', gap: 1, width: '100%' }}>
                <Box
                  sx={{
                  background: TEAL,
                  borderRadius: '2px',
                  flexShrink: 0,
                  height: 26,
                  width: 3,
                }}
                />

                <Box sx={{ flex: 1, minWidth: 0 }}>
                  <Typography
                    sx={{
                    color: NAVY,
                    fontSize: 12,
                    fontWeight: 700,
                    lineHeight: 1.3,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                  >
                    {option.name}
                  </Typography>
                  {option.code && (
                    <Typography
                      sx={{
                      color: alpha(NAVY, 0.42),
                      fontSize: 10,
                      lineHeight: 1.2,
                    }}
                    >
                      {option.code}
                    </Typography>
                  )}
                </Box>

                {option.unitPrice !== undefined && (
                  <Typography
                    sx={{
                    color: TEAL,
                    flexShrink: 0,
                    fontSize: 11,
                    fontVariantNumeric: 'tabular-nums',
                    fontWeight: 800,
                  }}
                  >
                    {/* eslint-disable-next-line max-len */}
                    {currencyCode} {getPriceFormatWithoutCurrency(option.unitPrice)}
                  </Typography>
                )}
              </Box>
            </li>
          );
        }}
        slotProps={{
          paper: {
            sx: {
              border: `1px solid ${alpha(TEAL, 0.15)}`,
              borderRadius: '12px',
              boxShadow: `0 8px 32px ${alpha(NAVY, 0.16)}`,
              mt: 0.5,
              '& .MuiAutocomplete-option': {
                '&:hover, &.Mui-focused': { background: alpha(TEAL, 0.08) },
                '&[aria-selected="true"]': { background: alpha(TEAL, 0.12) },
              },
            },
          },
        }}
        sx={{ width: '100%' }}
        value={null}
      />

      {selectedProduct && selectedProduct.isKgOrLitre && (
        <KgPopup
          handleAdd={handleAdd}
          handleCloseAlert={handleClosePopup}
          key={selectedProduct.id}
          open={openShowPopup}
          productId={selectedProduct.id}
          unitPrice={selectedProduct.unitPrice ?? 0}
        />
      )}
    </Box>
  );
};

export default React.memo(SearchProduct);
