import { Box, Grid, Paper, Stack, styled, Typography } from '@mui/material';
import React, { useMemo, useState } from 'react';
import Person3Icon from '@mui/icons-material/Person3';
import FileCopyIcon from '@mui/icons-material/FileCopy';
import AddIcon from '@mui/icons-material/Add';
import NewCustomer from '../../../Customer/component/NewCustomer';
import { useTranslation } from 'react-i18next';
import { useGetUserQuery } from '../../../posApi';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const cat = ['Cache In/Out', 'Recent sales', 'Pending sales', 'Pickup orders', 'Layaways'];

const FourthSection = () => {
  const { t } = useTranslation(['common', 'customer']);
  const [openAddCustomer, setOpenAddCustomer] = useState(false);

  const { data: companyData } = useGetUserQuery();

  const isImageEnabled = useMemo(() => {
    // eslint-disable-next-line max-len
    if (companyData?.data && typeof companyData.data === 'object' && 'company' in companyData.data) {
      // eslint-disable-next-line max-len
      return (companyData.data as { company: { isImageEnabled: boolean } }).company.isImageEnabled ?? true;
    }
    return false;
  }, [companyData]);

  return (
    <Box>
      <Grid
        container
        spacing={1}
      >
        {/* Add Customer */}
        <Grid
          item
          key="forth_1"
          md={1.5}
          sm={1.5}
          xs={4}
        >
          <Item
            onClick={() => setOpenAddCustomer(true)}
            sx={{
              background: 'linear-gradient(135deg, #f3e8ff 0%, #e9d5ff 100%)',
              position: 'relative',
            }}
          >
            <AddIcon
              sx={{
                fontSize: 16,
                color: '#7c3aed',
                position: 'absolute',
                top: 7,
                right: 7,
                opacity: 0.9,
              }}
            />
            <Stack
              alignItems="center"
              direction="column"
            >
              <Person3Icon sx={{ fontSize: 28, color: '#7c3aed' }} />
              <Typography sx={{ fontWeight: 700, fontSize: 11, color: '#0F1D4D', mt: '2px' }}>
                Customer
              </Typography>
            </Stack>
          </Item>
        </Grid>

        {/* Placeholder tiles */}
        {cat.map((item) => (
          <Grid
            item
            key={'forth_1_' + item}
            md={1.5}
            sm={1.5}
            xs={4}
          >
            <Item
              sx={{
                background: 'transparent',
                border: '1px dashed rgba(148,163,184,0.2)',
                boxShadow: 'none',
                cursor: 'default',
              }}
            />
          </Grid>
        ))}

        {/* X-Report */}
        <Grid
          item
          key="forth_2"
          md={1.5}
          sm={1.5}
          xs={4}
        >
          <Item
            sx={{
              background: 'linear-gradient(135deg, #ccfbf1 0%, #99f6e4 100%)',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <FileCopyIcon sx={{ fontSize: 26, color: '#0F8B8D' }} />
              <Typography sx={{ fontWeight: 700, fontSize: 11, color: '#0F1D4D', mt: '2px' }}>
                X-Report
              </Typography>
            </Stack>
          </Item>
        </Grid>

        {/* Filler */}
        <Grid
          item
          key="forth_3"
          md={1.5}
          sm={1.5}
          xs={4}
        >
          <Item
            sx={{
              background: 'transparent',
              border: '1px dashed rgba(148,163,184,0.2)',
              boxShadow: 'none',
              cursor: 'default',
              '&:hover': { transform: 'none', boxShadow: 'none' },
            }}
          />
        </Grid>
      </Grid>

      {openAddCustomer && (
        <NewCustomer
          data={undefined}
          handleCloseDialog={() => setOpenAddCustomer(false)}
          isImageEnabled={isImageEnabled}
          openModel={openAddCustomer}
          title={`${t('customer:addCustomer')}`}
        />
      )}
    </Box>
  );
};

export default React.memo(FourthSection);
