import { Badge, Box, Fab } from '@mui/material';
import ShoppingCartOutlinedIcon from '@mui/icons-material/ShoppingCartOutlined';
import React from 'react';
import Category from './Category';
import FourthSection from './FourthSection';
import FifthSection from './FifthSection';
import LastSection from './LastSection';
import PendingSales from './PendingSales';
import { useAppSelector } from '../../../../store/hooks';
import { selectBasketItems } from '../../store/SalesRichBasketSelector';

interface Props {
  isTablet: boolean;
  onCartOpen: () => void;
}

const Index = ({ isTablet, onCartOpen }: Props) => {
  const basketItems = useAppSelector(selectBasketItems);

  return (
    <Box
      sx={{
        '--tile-h': 'calc((100vh - 156px) / 7)',
        position: 'fixed',
        overflow: 'hidden',
        zIndex: 5,
        display: 'flex',
        flexDirection: 'column',
        pt: 0,
        pb: '8px',
        px: '8px',

        /* ── Desktop ── */
        left: { md: 'calc(38% + 12px)', lg: 'calc(33.333% + 12px)', xl: 'calc(30% + 12px)' },
        right: '8px',
        height: { md: 'calc(100vh - 72px)', lg: 'calc(100vh - 96px)' },

        /* ── Tablet: full viewport width, sits below AppBar ── */
        ...(isTablet && {
          left: 0,
          right: 0,
          height: 'calc(100vh - 64px)',
        }),
      }}
    >
      {/* Top sections */}
      <Box sx={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <Category />
        <FourthSection />
        <FifthSection />
        <PendingSales />
      </Box>

      {/* Spacer pushes LastSection to bottom */}
      <Box sx={{ flex: 1 }} />

      {/* Bottom — PAY row pinned */}
      <LastSection />

      {/* Cart FAB — tablet only */}
      {isTablet && (
        <Fab
          color="primary"
          onClick={onCartOpen}
          sx={{
            position: 'fixed',
            bottom: 28,
            right: 20,
            zIndex: 18,
            width: 58,
            height: 58,
            background: 'linear-gradient(135deg, #1a3bde 0%, #0c1f8f 100%)',
            boxShadow: '0 6px 20px rgba(0,20,137,0.40)',
            '&:hover': {
              background: 'linear-gradient(135deg, #2548e8 0%, #142ba8 100%)',
              boxShadow: '0 8px 28px rgba(0,20,137,0.55)',
            },
          }}
        >
          <Badge
            badgeContent={basketItems.length}
            color="error"
            max={99}
            sx={{
              '& .MuiBadge-badge': {
                fontSize: '0.65rem',
                fontWeight: 700,
                minWidth: 18,
                height: 18,
              },
            }}
          >
            <ShoppingCartOutlinedIcon sx={{ fontSize: '1.5rem', color: '#fff' }} />
          </Badge>
        </Fab>
      )}
    </Box>
  );
};

export default React.memo(Index);
