import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import {
  Box,
  CircularProgress,
  IconButton,
  InputAdornment,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';
import CloseIcon from '@mui/icons-material/Close';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import ErrorOutlineIcon from '@mui/icons-material/ErrorOutline';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import * as Yup from 'yup';
import { appColors, brandColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { useChangePasswordMutation, useGetUserQuery } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { IUserInfo } from '../../../core/Interface/user.interface';

interface IPassword {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
}

const ChangePassword = ({
  title,
  openModel = false,
  handleCloseDialog,
}: IPassword) => {
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const { data } = useGetUserQuery();
  const [changePassword, { isLoading }] = useChangePasswordMutation();
  const { showErrorMessage, showMessage } = useNotifier();

  const [showOld, setShowOld] = React.useState(false);
  const [showNew, setShowNew] = React.useState(false);
  const [showConfirm, setShowConfirm] = React.useState(false);

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const ChangePasswordSchema = Yup.object().shape({
    oldPassword: Yup.string().required('Please enter your old password'),
    newPassword: Yup.string().required('Please enter your new password'),
    confirmPassword: Yup.string()
      .required('Please retype your password.')
      .oneOf([Yup.ref('newPassword')], 'Your passwords do not match.'),
  });

  const formik = useFormik({
    initialValues: {
      oldPassword: null,
      newPassword: null,
      confirmPassword: null,
    },
    onSubmit: async (values) => {
      try {
        const temData = {
          userId: (data?.data as IUserInfo).id,
          oldPassword: values.oldPassword,
          newPassword: values.newPassword,
        };
        const passwordResponse = await changePassword(temData).unwrap();
        if (!passwordResponse.status) {
          showErrorMessage(passwordResponse.data as string);
        } else {
          handleClose();
          showMessage(passwordResponse.data as string);
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
    validationSchema: ChangePasswordSchema,
  });

  const fieldSx = {
    width: '100%',
    '& .MuiOutlinedInput-root': {
      borderRadius: 1.5,
      fontSize: '0.9rem',
      backgroundColor: '#f9fafb',
      transition: 'background-color 0.2s',
      '&:hover': { backgroundColor: '#f3f4f6' },
      '&.Mui-focused': {
        backgroundColor: '#fff',
        '& .MuiOutlinedInput-notchedOutline': { borderColor: brandColors.teal, borderWidth: 2 },
      },
      '&.Mui-error .MuiOutlinedInput-notchedOutline': { borderColor: appColors.carmineRed[100] },
    },
    '& .MuiInputBase-input': { py: 1.2 },
  };

  const FieldLabel = ({ text }: { text: string }) => (
    <Typography
      sx={{ fontSize: '0.8rem', fontWeight: 600, color: '#4b5563', mb: 0.75, display: 'block', letterSpacing: 0.2 }}
      variant="caption"
    >
      {text}
    </Typography>
  );

  const FieldError = ({ message }: { message?: string }) =>
    message ? (
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mt: 0.5 }}>
        <ErrorOutlineIcon sx={{ fontSize: 13, color: appColors.carmineRed[100] }} />
        <Typography sx={{ fontSize: '0.75rem', color: appColors.carmineRed[100], lineHeight: 1.3 }}>
          {message}
        </Typography>
      </Box>
    ) : null;

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="change-password-dialog"
          fullScreen={isMobile}
          maxWidth="xs"
          open={open}
          PaperProps={{
            sx: {
              borderRadius: isMobile ? 0 : 3,
              overflow: 'hidden',
              width: isMobile ? '100%' : 440,
              boxShadow: '0 16px 48px rgba(15,29,77,0.18)',
            },
          }}
        >
          {/* Gradient Header */}
          <Box
            sx={{
              background: HEADER_GRADIENT,
              px: 3,
              pt: 3,
              pb: 2.5,
              display: 'flex',
              alignItems: 'flex-start',
              justifyContent: 'space-between',
            }}
          >
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
              <Box
                sx={{
                  width: 40,
                  height: 40,
                  borderRadius: 2,
                  backgroundColor: 'rgba(255,255,255,0.18)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexShrink: 0,
                }}
              >
                <LockOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
              </Box>
              <Box>
                <Typography sx={{ color: '#fff', fontWeight: 700, fontSize: '1rem', lineHeight: 1.2 }}>
                  {title}
                </Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.75rem', mt: 0.25 }}>
                  Keep your account secure
                </Typography>
              </Box>
            </Box>
            <IconButton
              onClick={handleClose}
              size="small"
              sx={{
                color: 'rgba(255,255,255,0.8)',
                backgroundColor: 'rgba(255,255,255,0.12)',
                borderRadius: 1.5,
                '&:hover': { backgroundColor: 'rgba(255,255,255,0.22)', color: '#fff' },
              }}
            >
              <CloseIcon fontSize="small" />
            </IconButton>
          </Box>

          {/* Form Content */}
          <DialogContent sx={{ px: 3, pt: 3, pb: 1, backgroundColor: '#fff' }}>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5 }}>
              {/* Old Password */}
              <Box>
                <FieldLabel text="Current Password" />
                <TextField
                  autoComplete="current-password"
                  placeholder="Enter current password"
                  size="small"
                  type={showOld ? 'text' : 'password'}
                  {...formik.getFieldProps('oldPassword')}
                  error={!!(formik.errors.oldPassword && formik.touched.oldPassword)}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton
                          edge="end"
                          onClick={() => setShowOld((v) => !v)}
                          size="small"
                          sx={{ color: '#9ca3af', '&:hover': { color: brandColors.teal } }}
                        >
                          {showOld ? <VisibilityOff fontSize="small" /> : <Visibility fontSize="small" />}
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                  sx={fieldSx}
                />
                <FieldError message={formik.touched.oldPassword ? formik.errors.oldPassword : undefined} />
              </Box>

              {/* New Password */}
              <Box>
                <FieldLabel text="New Password" />
                <TextField
                  autoComplete="new-password"
                  placeholder="Enter new password"
                  size="small"
                  type={showNew ? 'text' : 'password'}
                  {...formik.getFieldProps('newPassword')}
                  error={!!(formik.errors.newPassword && formik.touched.newPassword)}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <IconButton
                          edge="end"
                          onClick={() => setShowNew((v) => !v)}
                          size="small"
                          sx={{ color: '#9ca3af', '&:hover': { color: brandColors.teal } }}
                        >
                          {showNew ? <VisibilityOff fontSize="small" /> : <Visibility fontSize="small" />}
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                  sx={fieldSx}
                />
                <FieldError message={formik.touched.newPassword ? formik.errors.newPassword : undefined} />
              </Box>

              {/* Confirm Password */}
              <Box>
                <FieldLabel text="Confirm New Password" />
                <TextField
                  autoComplete="new-password"
                  placeholder="Re-enter new password"
                  size="small"
                  type={showConfirm ? 'text' : 'password'}
                  {...formik.getFieldProps('confirmPassword')}
                  error={!!formik.errors.confirmPassword}
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        {formik.values.confirmPassword &&
                          !formik.errors.confirmPassword && (
                            <CheckCircleOutlineIcon
                              sx={{ fontSize: 18, color: appColors.forestGreen[100], mr: 0.5 }}
                            />
                          )}
                        <IconButton
                          edge="end"
                          onClick={() => setShowConfirm((v) => !v)}
                          size="small"
                          sx={{ color: '#9ca3af', '&:hover': { color: brandColors.teal } }}
                        >
                          {showConfirm ? <VisibilityOff fontSize="small" /> : <Visibility fontSize="small" />}
                        </IconButton>
                      </InputAdornment>
                    ),
                  }}
                  sx={fieldSx}
                />
                <FieldError message={formik.errors.confirmPassword} />
              </Box>
            </Box>
          </DialogContent>

          {/* Actions */}
          <DialogActions
            sx={{
              px: 3,
              pt: 2,
              pb: 3,
              gap: 1.5,
              backgroundColor: '#fff',
              borderTop: '1px solid #f3f4f6',
            }}
          >
            <Button
              fullWidth
              onClick={handleClose}
              sx={{
                height: 42,
                borderRadius: 1.5,
                fontWeight: 600,
                fontSize: '0.875rem',
                textTransform: 'none',
                borderColor: '#d1d5db',
                color: '#6b7280',
                '&:hover': { borderColor: '#9ca3af', backgroundColor: '#f9fafb' },
              }}
              variant="outlined"
            >
              Cancel
            </Button>
            <Button
              autoFocus
              disabled={
                !formik.isValid ||
                Object.keys(formik.touched).length === 0 ||
                isLoading
              }
              fullWidth
              onClick={() => formik.handleSubmit()}
              sx={{
                height: 42,
                borderRadius: 1.5,
                fontWeight: 600,
                fontSize: '0.875rem',
                textTransform: 'none',
                backgroundColor: brandColors.teal,
                color: '#fff',
                border: 'none',
                '&:hover': { backgroundColor: '#0a7375' },
                '&:disabled': { backgroundColor: '#c9ccd6', color: '#fff' },
                gap: 1,
              }}
              type="submit"
              variant="contained"
            >
              {isLoading && <CircularProgress size={16} sx={{ color: '#fff' }} />}
              {isLoading ? 'Updating...' : 'Change Password'}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(ChangePassword);
