import { PayloadAction, createSlice } from '@reduxjs/toolkit';
import {
  IBasketState,
  IAddCount,
} from '../../../core/Interface/property.interface';
import {
  BasketState,
  IPurchaseJewelBasketItem,
} from '../../../core/Interface/purchaseJewellery.interface';

const initialState: BasketState = {
  items: [],
  discount: 0,
  discountAsPercentage: false,
  mobile: '',
  nic: '',
  address: '',
  receiptNo: '',
  name: '',
  supplierName: '',
  supplierNameOrMobile: '',
};

export const basket = createSlice({
  name: 'purchaseJewelBasket',
  initialState,
  reducers: {
    addItem: (state, action: PayloadAction<IPurchaseJewelBasketItem>) => {
      const newItem = { ...action.payload };

      const existingItemIndex = state.items.findIndex(
        (item) => item.id === newItem.id
      );

      if (existingItemIndex !== -1) {
        state.items[existingItemIndex] = newItem;
      } else {
        state.items.push(newItem);
      }
      state.items.sort((a, b) =>
        a.id === newItem.id ? 1 : b.id === newItem.id ? -1 : 0
      );
    },
    removeItem: (state, action: PayloadAction<string>) => {
      const findItemIndex = state.items.findIndex(
        (element) => element.id === action.payload
      );
      if (findItemIndex > -1) {
        state = { ...state, items: state.items.splice(findItemIndex, 1) };
      }
    },
    removeBasket: (state) => {
      state = { ...initialState };
      return state;
    },
    addSupplierDetails: (state, action) => {
      state.supplierName = action.payload.supplierName;
      state.mobile = action.payload.mobile;
      state.nic = action.payload.nic;
      state.address = action.payload.address;
    },
    updateProductCount: (state, action: PayloadAction<IAddCount>) => {
      const { id, count, freeQty } = action.payload;
      const findItemIndex = state.items.findIndex(
        (element) => element.id === id
      );
      state.items[findItemIndex].quanity = count;
      state.items[findItemIndex].freeQty = freeQty || 0;
      state.items[findItemIndex].totalQty = (freeQty || 0) + (count || 0);
    },
    addDiscount: (
      state,
      action: PayloadAction<{ discount: number; discountAsPercentage: boolean }>
    ) => {
      state.discount = action.payload.discount;
      state.discountAsPercentage = action.payload.discountAsPercentage;
    },
    addFinalSummaryState: (state, action: PayloadAction<IBasketState>) => {
      state.finalSummaryStare = action.payload.finalSummaryStare;
    },
    
    clearBasket: (state) => {
      state.items = [];
      state.receiptNo = '';
      state.discount = 0;
      state.discountAsPercentage = false;
      state.name = '';
      state.mobile = '';
      state.nic = '';
      state.address = '';
      state.supplierName = '';
    },
  },
});

export const {
  addItem,
  removeItem,
  removeBasket,
  addSupplierDetails,
  updateProductCount,
  addDiscount,
  addFinalSummaryState,
  clearBasket,
 
} = basket.actions;

export const purchaseJewelBasketReducer = basket.reducer;

export { initialState as BasketInitialState };
